# ───────────── 教义
T=[("d1","👑","神的主权与护理","第4章是全书的中心：在罗马皇帝自称「主与神」的时代，约翰看见**天上的宝座**。所有的印、号、碗都**从宝座发出**；连撒但与兽的权柄也是「被赐给」的（{{启13:5}}，「赐给」在13章出现多次）。","启4–5；6:1-8；13:5-7；17:17",[("bc",13,"神的护理这一教义给了我们不可言喻的安慰，因为我们从此教义中得知"),("hc",28)],None),
   ("d2","🐑","基督：先知、祭司、君王","启示录是「**耶稣基督的启示**」（1:1）：他是诚实作见证的（先知）、用血洗净我们的（祭司）、世上君王的元首（君王）——**三重职分**都在 1:5-6 出现。","启1:5-6；5:5-10；19:11-16",[("hc",31),("hc",51)],('wsc',26)),
   ("d3","⛪","教会：受苦、作见证、得胜","教会是**灯台**（1:20）、**两个见证人**（11）、**妇人**（12）、**新妇**（19；21）。她的得胜方式是羔羊的方式：「羔羊的血和自己所见证的道」（{{启12:11}}）。真教会与假教会（巴比伦/淫妇）的分别贯穿全书。","启1:20；2–3；11:3-13；12；19:7-8；21:9-14",[("hc",54),("bc",29,"真教会的标志如下：她宣讲纯正的福音；她按照基督当初设立圣礼的样式施行圣礼；她为纠正错误、刑罚罪恶而执行教会纪律。")],('wcf',25,1)),
   ("d4","🐉","撒但、敌基督与属世权势","龙、海兽、地兽构成**仿冒的三一**；兽「似乎受了死伤」仿冒羔羊的复活。启示录教导基督徒尊重政权（参罗13），但当国家要求敬拜时，就成为兽。","启12–13；17；19:19-21；20:1-10",[("bc",36,"此外，每个人，无论他是什么身份、地位，处于何种境遇，都当顺服执政掌权的，向他们纳税，尊敬他们，并在不违反圣经的一切事上顺服他们。"),("hc",32)],None),
   ("d5","🛡️","圣徒的坚忍与蒙保守","受印的人在审判中蒙保守（7:3），名字记在**羔羊的生命册**上（13:8；21:27）；圣徒的忍耐就在这里（14:12）。神的保守与人的忍耐并行。","启3:10；7:1-8；13:8；14:12；17:14",[("dort",5,15,"然而，基督的新妇（教会）却视之为无价之宝，始终挚爱着它，并坚定地为之辩护；而其计划不可抗拒、其势不可阻挡的神，会确保教会继续如此行。"),("hc",1)],('wcf',17,1)),
   ("d6","🕊️","死后：居间状态","祭坛下的灵魂（6:9-11）「在主里面而死的人有福了」（14:13）：信徒死后灵魂立即与基督同在，有意识地安息与等候，并没有「灵魂睡觉」或炼狱。","启6:9-11；7:9-17；14:13；20:4",[("hc",57)],('wcf',32,1)),
   ("d7","⚖️","再来与最后审判","一次、有形、荣耀的再来（1:7；19:11）；白色大宝座前「照他们所行的受审判」（20:12）。对信徒是安慰，对逼迫者是可怕的。","启1:7；6:16-17；14:14-20；19:11-21；20:11-15；22:12",[("bc",37),("hc",52)],('wcf',33,1)),
   ("d8","🌅","复活与新天新地","不是灵魂逃离物质世界，而是**身体复活**与**万物更新**（21:5「我将一切都更新了」）。神的帐幕在人间——圣约的完成。","启20:4-6,13；21:1–22:5",[("hc",58),("dort",3,8,"此外，他诚挚地应许将永生和灵魂的安息赐给所有到他面前且信他的人。")],('wsc',38)),
   ("d9","🔥","地狱与永刑","火湖、第二次的死（20:14；21:8）：圣经对永刑的严肃教导。神的公义在审判中被赞美（16:5-7；19:1-2）。","启14:9-11；16:5-7；19:1-3；20:10-15；21:8",[("dort",3,7,"至于那些没有得此恩典的人，我们应该像使徒约翰一样，赞美神所行的审判严厉而又公义，决不应该好奇地窥探隐秘之事。")],('wcf',33,2)),
   ("d10","🙏","敬拜与祷告：愿你的国降临","全书充满敬拜；圣徒的祷告像香（5:8；8:3-4），神用审判回应「伸冤」的祷告（6:10 → 8:5）。全书以「主耶稣啊，我愿你来」（22:20）结束——这就是主祷文第二个祈求。","启5:8；8:3-5；19:10；22:8-9,17,20",[("hc",123),("hc",117,"第一，我们必须为神所吩咐我们祈求的一切事，真心地呼求那位在圣经中启示自己的独一真神。")],('wcf',33,3))]
def doctrine():
    b=['<div class="dmap glass reveal"><div class="dm-c">🌅 启示录教义<br><small>十大主题</small></div><div class="dm-r">'+"".join(f'<a href="#{i}" class="dm-n" style="--i:{k}">{ic} {t}</a>' for k,(i,ic,t,*_) in enumerate(T))+'</div></div>']
    for i,ic,t,s,refs,qs,w in T:
        b.append(f'<h2 id="{i}">{ic} {t}</h2><div class="card glass"><p>{md(s)}</p><p class="refs">📖 主要经文：{esc(refs)}</p></div>')
        b.append('<div class="confs">'+"".join(cq(q) for q in qs)+(wq(w[0],*w[1:]) if w and w[0]=='wcf' else (wq(w[0],w[1]) if w else ""))+'</div>')
    b.append('<h2 id="dz">📋 末世教义：三项联合信条 vs 威斯敏斯特</h2>'+tbl(["主题","三项联合信条","威斯敏斯特标准"],[("再来","BC 37：有形有体、大荣耀；HC 52：安慰","WCF 33.1-3；WLC 88"),("死后","HC 57：灵魂立刻被提到基督那里","WCF 32.1；WSC 37；WLC 86"),("复活","HC 57-58；BC 37：与以前的身体联合","WCF 32.2-3；WSC 38；WLC 87"),("审判","BC 37：案卷展开（启20:12）；对选民是喜乐","WCF 33.1-2；WLC 89-90"),("千禧年","未明言；BC 37 的次序与无千禧年一致","未明言；后千禧年与无千禧年者都接受"),("敌基督","未明言","WCF 25.6（原版）：教皇是敌基督"),("语气","**安慰性**（BC 37：「我们极其盼望那日的到来」）","**系统性**、警醒（33.3）")]))
    b.append(wq('wsc',37)+wq('wlc',90))
    return "".join(b)
# ───────────── 三项联合信条
