    b.append('<h2 id="f1">一、三份文件的身份证</h2><div class="forms3">'+"".join(f'<div class="f3 glass reveal" style="--gc:{c}"><span class="fi">{i}</span><b>{n}</b><small>{y}</small><ul>'+"".join(f'<li>{md(x)}</li>' for x in L)+'</ul></div>' for i,n,y,c,L in [
        ("📗","比利时信条","1561 · 德布利（Guido de Brès）","#3fd39a",["**37 条**，信条体（「我们相信……」）","处境：西班牙腓利二世的逼迫；向政府表明改革宗是守法公民","内容：神、圣经、三一、创造、罪、基督、称义、教会、圣礼、政府、末世","**结尾 = 第37条最后审判**，引启20:12；21:4；22:20"]),
        ("📘","海德堡要理问答","1563 · 乌尔西努、俄利维亚努","#4fb3ff",["**129 问**，分 **52 主日**（一年讲完）","处境：选帝侯腓德烈三世要教导年轻人、统一信仰","结构：**罪 — 救 — 恩**（愁苦、拯救、感恩）","语气：个人、安慰（「我唯一的安慰」）"]),
        ("📕","多特信经","1618–19 · 国际性的多特大会","#ff6b6b",["**五项教义**（第三、四项合并），每项含正面陈述与驳斥错谬","处境：阿米念派「抗辩书」五点","内容：无条件拣选、有限的救赎、全然败坏、不可抗拒的恩典、圣徒蒙保守","语气：精确、牧养（确据与安慰）"])])+'</div>')
