def hcrecite(n):
    q=HCQ[n]; ans=strip(q['answer']); qq=strip(q['question'])
    L=[x for x in re.split(r'(?<=[。；！？])',ans) if x.strip()]; QUOTES.append(('hc',n,"".join(L)))
    body="".join(f'<p class="rl"><span class="rn">{i+1}</span><span class="rt">{esc(x)}</span></p>' for i,x in enumerate(L))
    return (f'<article class="recite hc glass" id="r-hc{n}"><header><span class="ric">📘</span><h4>第{n}问：{esc(qq)}</h4><a href="{q["url"]}" target="_blank" rel="noopener">CCI 原文 ↗</a></header>'
            '<div class="rmodes" role="group" aria-label="背诵模式"><button class="on" data-m="read">📖 阅读</button><button data-m="hint">🔤 首字提示</button><button data-m="hide">🙈 遮盖</button><button data-m="big">🔠 大字</button><button class="tts" data-m="tts">🔊 朗读</button></div>'
            f'<div class="rbody">{body}</div></article>')
